#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

long long powMod(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k, l;
    cin >> n >> k >> l;

    vector<long long> fac(n + 1, 1);
    for (int i = 1; i <= n; i++) {
        fac[i] = (fac[i - 1] * i) % mod;
    }

    vector<vector<long long>> dp(2 * n + 1, vector<long long>(2 * n + 2, 0));
    dp[0][0] = 1;

    for (int i = 1; i <= 2 * n; i++) {
        for (int j = 0; j <= min(i, n); j++) {
            if (j > 0) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % mod;
            }
            dp[i][j] = (dp[i][j] + dp[i - 1][j + 1] * (j + 1) % mod) % mod;
        }
    }

    long long ans = 0;
    for (int i = k; i <= 2 * n; i++) {
        for (int j = k; j <= n; j++) {
            long long temp = (dp[i][j] * dp[2 * n - i][j]) % mod;
            temp = (temp * fac[j]) % mod;
            ans = (ans + temp) % mod;
        }
    }

    long long inv1 = powMod(dp[2 * n][0], mod - 2);
    long long inv2 = powMod(2 * n + 1, mod - 2);
    cout << (l * ans % mod) * inv1 % mod * inv2 % mod << "\n";

    return 0;
}
